import{_ as a,o as e,c as n,a5 as r}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"854-根据文件夹创建时间-修改时间追加到每个文件夹名后边进行重命名","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["修改时间改名","创建时间改名","批量改名","文件夹重命名","时间戳命名"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/文件及文件夹批处理/854-根据文件夹创建时间-修改时间追加到每个文件夹名后边进行重命名.md","filePath":"md/文件及文件夹批处理/854-根据文件夹创建时间-修改时间追加到每个文件夹名后边进行重命名.md"}'),o={name:"md/文件及文件夹批处理/854-根据文件夹创建时间-修改时间追加到每个文件夹名后边进行重命名.md"};function l(s,t,p,i,h,_){return e(),n("div",null,[...t[0]||(t[0]=[r('<p>批量为文件夹名后追加创建时间或修改时间。会按创建时间或修改时间给每个子文件夹追加日期，勾选具体时间后会用“2024-05-01-15时15分00秒”这样的格式。若同一时间有多个文件夹，程序会自动加“(1)(2)”防止重名。</p><p>【1】、支持的文件格式：只对文件夹有效</p><p>【2】、是否支持子文件夹穿透：支持</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208215457176520209734700.jpg" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p>支持按创建时间或修改时间排序，时间可选精确到时分秒，避免重复时会自动加括号序号。</p><p>已有相似日期后缀会先清理，避免越改越长。</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p>先在界面输入或选择目标文件夹路径。</p><p>选择“按创建日期”或“按修改日期”。</p><p>可勾选“重命名时包含具体时间”，勾上则使用“HH时MM分SS秒”格式。</p><p>点击“开始程序”启动，日志区会输出处理进度。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208215517176520211748446.png" alt=""></p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><p>如果有一批摄影素材文件夹，需要按拍摄时间顺序整理，选中总目录，勾选包含时间，就能得到类似“素材-2024-05-01-15时15分00秒”的名字，顺序一目了然。若同一时间有多个文件夹，程序会自动加“(1)(2)”防止重名。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208215640176520220084537.png" alt=""></p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q 日志显示“指定的路径不是文件夹”</strong><br> A 检查输入路径是否正确，确保选择的是文件夹而不是文件。</p><p><strong>Q 勾选了时间但没有看到时分秒</strong><br> A 确认勾选“重命名时包含具体时间”，运行时会生成“HH时MM分SS秒”格式。</p><p><strong>Q 已经带日期的文件夹会不会越改越长</strong><br> A 程序会先清理旧的“-YYYY-MM-DD-HH时MM分SS秒(序号)”后缀，再追加新的格式。</p><p><strong>Q 遇到重名冲突怎么处理</strong><br> A 程序会自动追加“(1)(2)”等序号，直到不再冲突。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后双击运行即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251208220323176520260396523.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2240.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2240.html</a></p>',32)])])}const d=a(o,[["render",l]]);export{c as __pageData,d as default};
